package paymenttrace
import("context";"database/sql";_ "github.com/go-sql-driver/mysql")
type MySQLPort struct{db *sql.DB};func OpenMySQL(ctx context.Context,dsn string)(*MySQLPort,error){db,e:=sql.Open("mysql",dsn);if e!=nil{return nil,e};c,x:=context.WithTimeout(ctx,MaxTimeout);defer x();if e=db.PingContext(c);e!=nil{db.Close();return nil,e};return &MySQLPort{db},nil};func(p *MySQLPort)Close()error{return p.db.Close()};func(p *MySQLPort)ReadTrace(ctx context.Context,q Query)([]Record,error){rows,e:=p.db.QueryContext(ctx,"SELECT tenant_id,event_id,event_digest,ack_cursor,projection_revision,migration_id,migration_checksum,result_code,ordering,duration_ms FROM payment_trace_metadata WHERE tenant_id=? ORDER BY ordering,event_id LIMIT ?",q.TenantID,q.Limit);if e!=nil{return nil,e};defer rows.Close();var out []Record;for rows.Next(){var r Record;if e=rows.Scan(&r.TenantID,&r.EventID,&r.EventDigest,&r.AcknowledgementCursor,&r.ProjectionRevision,&r.MigrationID,&r.MigrationChecksum,&r.ResultCode,&r.Ordering,&r.DurationMS);e!=nil{return nil,e};out=append(out,r)};return out,rows.Err()}
